import{_ as t,o,c as e,a0 as i}from"./chunks/framework.L_oL6aia.js";const m=JSON.parse('{"title":"Shadowrocket（小火箭）安装与使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shadowrocket.md","filePath":"guide/shadowrocket.md"}'),l={name:"guide/shadowrocket.md"};function r(s,a,c,h,p,d){return o(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="shadowrocket-小火箭-安装与使用教程" tabindex="-1">Shadowrocket（小火箭）安装与使用教程 <a class="header-anchor" href="#shadowrocket-小火箭-安装与使用教程" aria-label="Permalink to &quot;Shadowrocket（小火箭）安装与使用教程&quot;">​</a></h1><p>Shadowrocket，又称&quot;小火箭&quot;，是 iOS 平台上最受欢迎的科学上网工具之一，支持多种协议（如 SSR、SS、Vmess 等），稳定性高、操作简单，是新手入门的首选工具。</p><h2 id="一、下载-shadowrocket-小火箭" tabindex="-1">一、下载 Shadowrocket（小火箭） <a class="header-anchor" href="#一、下载-shadowrocket-小火箭" aria-label="Permalink to &quot;一、下载 Shadowrocket（小火箭）&quot;">​</a></h2><h3 id="软件信息" tabindex="-1">软件信息 <a class="header-anchor" href="#软件信息" aria-label="Permalink to &quot;软件信息&quot;">​</a></h3><ul><li><strong>唯一正版地址</strong>（仅限美区）：<a href="https://apps.apple.com/us/app/shadowrocket/id932747118" target="_blank" rel="noreferrer">https://apps.apple.com/us/app/shadowrocket/id932747118</a></li><li><strong>售价</strong>：2.99 美元买断制</li><li><strong>支持设备</strong>：iPhone / iPad</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>App 仅在美国区 App Store 上架，其他地区可能是假冒应用，谨防误装扣费。</p></div><h3 id="获取方式" tabindex="-1">获取方式 <a class="header-anchor" href="#获取方式" aria-label="Permalink to &quot;获取方式&quot;">​</a></h3><p>推荐使用自己的<strong>美区 Apple ID</strong> 购买下载。</p><div class="tip custom-block"><p class="custom-block-title">购买小火箭 ID</p><p>链接：<a href="https://ios.mimy.cc/item/23" target="_blank" rel="noreferrer">https://ios.mimy.cc/item/23</a></p></div><h3 id="安装步骤" tabindex="-1">安装步骤 <a class="header-anchor" href="#安装步骤" aria-label="Permalink to &quot;安装步骤&quot;">​</a></h3><ol><li>登录美区 Apple ID</li><li>打开 App Store，搜索 &quot;Shadowrocket&quot; 或点击上方链接跳转</li><li>下载并安装应用</li><li>安装完成后立即退出共享账号（如使用）</li></ol><img src="https://img.mimy.cc/appleid.webp" alt="登录美区 Apple ID"><h2 id="二、导入节点-推荐使用订阅链接" tabindex="-1">二、导入节点（推荐使用订阅链接） <a class="header-anchor" href="#二、导入节点-推荐使用订阅链接" aria-label="Permalink to &quot;二、导入节点（推荐使用订阅链接）&quot;">​</a></h2><h3 id="获取订阅链接" tabindex="-1">获取订阅链接 <a class="header-anchor" href="#获取订阅链接" aria-label="Permalink to &quot;获取订阅链接&quot;">​</a></h3><p>前往机场官网复制你的订阅链接。</p><img src="https://img.mimy.cc/sp222.webp" alt="复制订阅链接"><h3 id="添加订阅链接" tabindex="-1">添加订阅链接 <a class="header-anchor" href="#添加订阅链接" aria-label="Permalink to &quot;添加订阅链接&quot;">​</a></h3><ol><li>打开 Shadowrocket，点击右上角 <strong>+</strong> 按钮</li></ol><img src="https://img.mimy.cc/sx111.webp" alt="点击右上角加号按钮"><ol start="2"><li>设置如下： <ul><li><strong>类型</strong>：选择 <code>Subscribe</code></li><li><strong>URL</strong>：粘贴你的订阅链接</li><li><strong>备注</strong>：可自定义命名（例如：速云1）</li><li>点击<strong>完成</strong>，系统自动导入节点</li></ul></li></ol><img src="https://img.mimy.cc/sx222.webp" alt="填写订阅信息"><h2 id="三、启动代理" tabindex="-1">三、启动代理 <a class="header-anchor" href="#三、启动代理" aria-label="Permalink to &quot;三、启动代理&quot;">​</a></h2><ol><li>在主界面下方选择你要使用的节点（服务器）</li><li>打开页面顶部的主开关，即可启用 VPN 功能</li></ol><img src="https://img.mimy.cc/sx333.webp" alt="选择节点"><img src="https://img.mimy.cc/sx444.webp" alt="开启主开关连接"><h2 id="四、其他提示" tabindex="-1">四、其他提示 <a class="header-anchor" href="#四、其他提示" aria-label="Permalink to &quot;四、其他提示&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>首次连接时会弹出添加 VPN 配置提示，请点击&quot;允许&quot;。</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>如果订阅节点更新失败，可尝试刷新订阅或重新导入。</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>建议开启&quot;启动时自动连接&quot;和&quot;后台运行&quot;。</p></div><h2 id="五、支持的代理协议" tabindex="-1">五、支持的代理协议 <a class="header-anchor" href="#五、支持的代理协议" aria-label="Permalink to &quot;五、支持的代理协议&quot;">​</a></h2><p>Shadowrocket 支持以下协议：</p><ul><li>Shadowsocks（SS）</li><li>ShadowsocksR（SSR）</li><li>Vmess（部分机场支持）</li><li>HTTP / HTTPS</li><li>SOCKS5</li></ul>',32)])])}const u=t(l,[["render",r]]);export{m as __pageData,u as default};
